def allMetadata[T](raster: RDD[ITile[T]]): Array[RasterMetadata] =
    // For efficiency, we assume that all metadata in each partition is the same
    raster.mapPartitions(tiles => {
        if (tiles.hasNext) {
          Some(tiles.next().rasterMetadata).iterator
        } else {
          Option.empty[RasterMetadata].iterator
        }
      }).distinct()
      .collect()

def gridToGridTransform(sourceMetadata: RasterMetadata, targetMetadata: RasterMetadata): MathTransform = {
    val sourceG2M: MathTransform = new AffineTransform2D(sourceMetadata.g2m)
    val sourceM2TargetM: MathTransform = Reprojector.findTransformationInfo(sourceMetadata.srid, targetMetadata.srid).mathTransform
    val targetM2G: MathTransform = new AffineTransform2D(targetMetadata.g2m).inverse()
    ConcatenatedTransform.create(ConcatenatedTransform.create(sourceG2M, sourceM2TargetM), targetM2G)
  }

