def reshapeBilinear[T: ClassTag](raster: RasterRDD[T], targetMetadataConv: RasterMetadata => RasterMetadata,
                             numPartitions: Int = 0): RasterRDD[T] = {
    val intermediateReshapedTiles: RDD[(Int, ReshapeTile[T])] = raster.flatMap(sourceTile => {
      val targetMetadata = targetMetadataConv(sourceTile.rasterMetadata)
      val allTargetTiles = ReshapeTile.getTargetTilesForSourceTiles(sourceTile.tileID, targetMetadata, sourceTile.rasterMetadata)
      allTargetTiles.map(targetTileID => {
        val reshapeTile = new ReshapeTile[T](targetTileID, targetMetadata, sourceTile.rasterFeature)
        reshapeTile.addTile(sourceTile)
        (targetTileID, reshapeTile)
      })
    })
    intermediateReshapedTiles.reduceByKey((interTile1, interTile2) => interTile1.merge(interTile2))
      .map(x => x._2.resultTile)
  }

